mapper.select:
select `wc`.`id`,
`w`.`date`,
`wc`.`start_work_time`,
`wc`.`end_work_time`,
`wc`.`mark`,
`wc`.`start_real_time`,
`wc`.`end_real_time`
from `arrange_work` w
left join `arrange_work_classes` wc on w.`arrange_work_classes_ids` like CONCAT('%',wc.`id`,'%')
where `wc`.`id` is not null

    and w.`staff_id` = #{param.userId}


    and w.`date` = #{param.date}


    and w.`group_id` = #{param.groupId}


    and wc.`start_real_time` >= #{param.period.begin}


    and wc.`start_real_time` < #{param.period.end}

order by wc.`start_real_time` asc



    AND aw.`staff_id` = #{userId}


    AND aw.`date` = #{date}


    AND awc.`start_real_time` > #{dateTime}


order by awc.`start_real_time` asc limit 10



    AND aw.`staff_id` = #{userId}


    AND aw.`date` = #{date}


    AND
    (
    (
    awc.`end_real_time` <= #{dateTime}
    AND awc.`after_end_real_time` IS NULL
    )
    OR
    (
    awc.`end_real_time` <= #{dateTime}
    AND awc.`after_end_real_time` >= #{dateTime}
    )
    )

order by awc.`end_real_time` desc



    AND aw.`staff_id` = #{userId}


    AND aw.`date` = #{date}


    AND awc.`end_real_time` <= #{dateTime}

order by awc.`end_real_time` desc limit 10

select aw.`id` AS `workId`, aw.`group_id` AS `attendanceGroupId`, aw.`staff_id`, aw.`date` AS `clockDate`, awc.`id` AS `arrangeClassesId`, awc.`start_work_time`, awc.`end_work_time`, awc.`start_real_time`, awc.`end_real_time`, awc.`before_start_real_time`, awc.`after_start_real_time`, awc.`before_end_real_time`, awc.`after_end_real_time`, awc.`mark`, aw.`tenant` from `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%') where 1 = 1
AND aw.`staff_id` = #{userId}
AND awc.`start_real_time` >= #{period.begin} AND awc.`start_real_time` <= #{period.end}
AND awc.`end_real_time` >= #{period.begin} AND awc.`end_real_time` <= #{period.end}

select aw.`id` AS `workId`, aw.`group_id` AS `attendanceGroupId`, awc.`start_work_time`, awc.`end_work_time`, awc.`start_real_time`, awc.`end_real_time` from `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%') where 1 = 1
AND aw.`staff_id` = #{userId}
AND aw.`date` = #{date}
AND awc.`id` = #{arrangeClassesId}

select
awc.`rest_start_real_time`,
awc.`rest_end_real_time`
from `arrange_work` aw
LEFT JOIN  `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%')
where 1 = 1

    AND aw.`staff_id` = #{userId}


    AND awc.rest_start_real_time >= #{period.begin}
    AND awc.rest_end_real_time <= #{period.end}

-- 这里有问题，在连表条件用like时，查询条件用in,会导致报错，有空可以深究一下什么问题 select aw.`staff_id` from `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%') where 1= 1
AND aw.`staff_id` in
#{id}
AND awc.`start_real_time` <= #{date} AND awc.`end_real_time` >= #{date}

select awc.`id`, awc.`classes_id`, awc.`name`, awc.`start_work_time`, awc.`end_work_time` from `arrange_work` aw INNER JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%') where 1=1
AND aw.`staff_id` = #{userId}
AND aw.date = #{date}
order by awc.`start_real_time`

select CONCAT(aw.`date`,' ',awc.`start_work_time`, ':00') as `start_real_time`, awc.`end_real_time`, awc.`rest_start_real_time`, awc.`rest_end_real_time` from `arrange_work` aw LEFT JOIN `arrange_work_classes` awc ON aw.`arrange_work_classes_ids` LIKE CONCAT('%',awc.`id`,'%') where 1 = 1
AND aw.`staff_id` = #{staffId}
AND awc.`start_real_time` < #{period.end} AND awc.`end_real_time` > #{period.begin}
order by awc.`start_real_time`
